import { kgToGo } from "./rules.js";
import {load } from "../js/storage.js"

const state = load();

function render(){
    document.getElementById("nickname").textContent = state.nickname;
    document.getElementById("level").textContent = `Level : ${state.level}`;
    document.getElementById("xp").textContent = `${state.xp} / ${state.xpNeed}`;
}

render();import { kgToGo } from "../js/rules.js";

import { load, save } from "../js/storage.js";

const state = load();

const dialog = document.getElementById("project-dialog");
document.getElementById("new-project").addEventListener("click", () => dialog.showModal());
document.getElementById("cancel-project-creation").addEventListener("click", () => dialog.close());
document.getElementById("confirm-project-creation").addEventListener("click", () => dialog.close());

const form = document.getElementById("project-form");
form.addEventListener("submit", () => {
    const data = new FormData(form);
    const project = {
        title : data.get("title"),
        description : data.get("des"),
        due : data.get("due"),
    };
    state.projects.push(project);
    save(state);
    form.reset();
    render();
})

function renderProjects(){
    const list = document.getElementById("projects-list");
    list.replaceChildren();
    for (const project of state.projects){
        const li = document.createElement("li");
        li.textContent = project.title;
        list.appendChild(li);
    }
}

function render(){
    renderProjects();
}

render();export function kgToGo(current, target)
{
    let count = target - current;
    if (current >= target)
        count = 0;
    if (count > target)
        count = "Error";
    return (count);
}

export function percentDone(current, target)
{
    let percent = current / target * 100;
}

export function formatLevel(lvl, current, target)
{
    let count = kgToGo(current, target);
    return (`Level ${lvl} : ${count}/100`);
}
const state = {
    player : "Arthurooo",
    nickname : "loser",
    level : 1,
    xp : 0,
    xpNeed : 100,
    projects : [],
};

export function save(state){
    const text = JSON.stringify(state);
    localStorage.setItem("Current State", text);
}

export function load(){
    const saved = localStorage.getItem("Current State");
    if (saved){
        return JSON.parse(saved);
    }
    else{
        return state;
    }
}

